import manifest from "./manifest";

// The /product-demo catalogue. manifest.ts is generated by
// product-demo-assets/tools/build-hls.mjs from the recordings, and lists
// paths relative to the CDN that serves the HLS assets. Its base URL comes
// from VITE_PRODUCT_DEMO_CDN_URL at build time (no bucket names or account
// details live in the code). Quality levels are not listed here: the player
// reads them from each stream's master playlist.

export type Chapter = { title: string; startTime: number };
export type DemoVideo = {
  id: string;
  title: string;
  description: string;
  /** Seconds. */
  duration: number;
  /** Date recorded (YYYY-MM-DD). */
  recorded: string;
  thumbnail: string;
  hls: string;
  subtitles: { en: string; hi: string };
  chapters: Chapter[];
  /** Heights in the master playlist, for the catalogue only. */
  qualities: number[];
  /** Narration languages (HLS audio renditions). */
  audio?: string[];
};
export type DemoModule = {
  id: string;
  title: string;
  description: string;
  icon: string;
  videos: DemoVideo[];
};

export const MODULES = manifest.modules as DemoModule[];

/** The complete tour (product-demo-assets/tools/film.mjs): every part of
 *  Praesto in one film. Not one of the modules; the page features it. */
export const FILM = (manifest as unknown as { film?: DemoVideo }).film ?? null;
export const TOUR: DemoModule | null = FILM
  ? {
      id: "tour",
      title: "The Complete Tour",
      description:
        "Every part of Praesto in one film, from setting up your organisation to AI and support, recorded in the real product.",
      icon: "play",
      videos: [FILM],
    }
  : null;

const base = (import.meta.env.VITE_PRODUCT_DEMO_CDN_URL ?? "").replace(
  /\/+$/,
  "",
);
/** Whether this build knows where the videos are. */
export const CDN_CONFIGURED = base.length > 0;
export const cdn = (path: string) => `${base}/${path.replace(/^\/+/, "")}`;

/**
 * A thumbnail as the page loads it: always as a CORS request (crossOrigin
 * on every <img>), and under its own URL. The player's poster is a CORS
 * request (<video crossorigin>), and S3 sends CORS headers, and Vary:
 * Origin, only when asked; a plain <img> of the same URL would be cached
 * for a year without them and then refused for the poster. The query string
 * keeps clear of copies browsers cached that way. (Not "?cors": S3 reads
 * that as its own CORS API and answers 403. Link previews and search use
 * the plain URL: no CORS there.)
 */
export const thumbnailSrc = (path: string) => `${cdn(path)}?img=1`;

export function findVideo(id: string | null | undefined) {
  if (TOUR && FILM && id === FILM.id) return { module: TOUR, video: FILM };
  for (const m of MODULES) {
    const v = m.videos.find((x) => x.id === id);
    if (v) return { module: m, video: v };
  }
  return null;
}

/** Every video in play order: the complete tour, then each module's demos.
 *  Previous / Next and Up Next move along this list. */
export const ORDER: { module: DemoModule; video: DemoVideo }[] = [
  ...(TOUR && FILM ? [{ module: TOUR, video: FILM }] : []),
  ...MODULES.flatMap((m) => m.videos.map((v) => ({ module: m, video: v }))),
];

/** A video's own page: what Share copies, and what link previews show. */
export const watchPath = (id: string) => `/watch/${encodeURIComponent(id)}`;

/** 75 → "1:15". */
export function clock(seconds: number) {
  const s = Math.max(0, Math.floor(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

/** The chapter playing at `t`. */
export function chapterAt(chapters: Chapter[], t: number) {
  let i = 0;
  for (let k = 0; k < chapters.length; k++)
    if (chapters[k].startTime <= t + 0.05) i = k;
  return i;
}
